// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 1000 ether);
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 365 days);

        // read the actor's current credited balance via the public getter (struct returns a tuple)
        uint256 before;
        { (, uint256 b0) = c.Acc(actor); before = b0; }

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount, gas: 200000}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterB;
        { (, uint256 b1) = c.Acc(actor); afterB = b1; }

        // General rule: every successful Put credits exactly msg.value to the caller's balance.
        assertTrue(ok ? (afterB == before + amount) : (afterB == before));
    }
}

