pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor, uint256 unlockTime) public {
        vm.assume(amount1 > 0);
        vm.assume(amount2 > type(uint256).max - amount1); // second deposit overflows the credited balance
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));

        vm.deal(actor, amount2);
        vm.prank(actor);
        c.Put{value: amount1}(unlockTime);

        vm.prank(actor);
        bool ok;
        try c.Put{value: amount2}(unlockTime) { ok = true; } catch { ok = false; }

        // Rule: a deposit that would overflow the caller's credited balance always reverts.
        assertTrue(!ok);
    }
}

